import re
from functools import cmp_to_key

def parse_version(version_str):
    """Parses a SemVer 2.0.0 string into its components."""
    # Remove optional 'v' prefix
    if version_str.startswith('v'):
        version_str = version_str[1:]

    # Regex to split core, pre-release and build metadata
    # Pattern: MAJOR.MINOR.PATCH (optional -PRERELEASE) (optional +BUILD)
    pattern = r'^(\d+\.\d+\.\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$'
    match = re.match(pattern, version_str)
    if not match:
        raise ValueError(f"Invalid SemVer string: {version_str}")

    core_part, pre_release_part, build_part = match.groups()

    # Parse core (MAJOR.MINOR.PATCH)
    core_parts = core_part.split('.')
    parsed_core = []
    for part in core_parts:
        if not part.isdigit():
            raise ValueError(f"Core parts must be digits: {part}")
        val = int(part)
        # Check for leading zeros (except '0')
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Leading zeros not allowed in core version: {part}")
        parsed_core.append(val)

    # Parse pre-release identifiers
    parsed_pre = []
    if pre_release_part:
        for identifier in pre_release_part.split('.'):
            if not re.match(r'^[0-9A-Za-z-]+$', identifier):
                raise ValueError(f"Invalid pre-release identifier: {identifier}")
            if identifier.isdigit():
                # Numeric identifiers must not have leading zeros (already checked by regex and int conversion)
                # But we need to ensure it's actually numeric for comparison logic
                parsed_pre.append(('num', int(identifier)))
            else:
                parsed_pre.append(('alpha', identifier))

    return {
        'core': tuple(parsed_core),
        'pre': parsed_pre,
        'build': build_part # Build metadata is ignored in precedence
    }

def compare_identifiers(id1, id2):
    """Compares two pre-release identifiers."""
    type1, val1 = id1
    type2, val2 = id2

    if type1 == 'num' and type2 == 'num':
        if val1 < val2: return -1
        if val1 > val2: return 1
        return 0
    elif type1 != 'num' and type2 != 'num':
        if val1 < val2: return -1
        if val1 > val2: return 1
        return 0
    else:
        # One is numeric, one is alpha. Numeric has lower precedence.
        return -1 if type1 == 'num' else 1

def compare_versions(v1_str, v2_str):
    """Compares two SemVer strings."""
    v1 = parse_version(v1_str)
    v2 = parse_version(v2_str)

    # 1. Compare core parts (MAJOR.MINOR.PATCH)
    if v1['core'] < v2['core']: return -1
    if v1['core'] > v2['core']: return 1

    # 2. Handle pre-release precedence
    # A normal version has higher precedence than a pre-release version.
    if not v1['pre'] and v2['pre']:
        return 1
    if v1['pre'] and not v2['pre']:
        return -1

    # Both have pre-releases or both don't (and they are equal so far)
    if not v1['pre'] and not v2['pre']:
        return 0

    # Both have pre-releases, compare them identifier by identifier
    for i in range(min(len(v1['pre']), len(v2['pre']))):
        res = compare_identifiers(v1['pre'][i], v2['pre'][i])
        if res != 0:
            return res

    # If all common identifiers are equal, the one with more parts has higher precedence
    if len(v1['pre']) < len(v2['pre']):
        return -1
    elif len(v1['pre']) > len(v2['pre']):
        return 1
    else:
        return 0

def compare(a: str, b: str) -> int:
    """Compares two SemVer strings. Returns -1 if a < b, 0 if a == b, 1 if a > b."""
    try:
        return compare_versions(a, b)
    except ValueError as e:
        raise ValueError(str(e))

def sort_versions(versions: list[str]) -> list[str]:
    """Sorts versions in ascending order. Stable sort is used by Python's sorted()."""
    # We use a key that returns the comparison result relative to an empty/base state, 
    # but since we need a custom comparator for compare_versions, cmp_to_key is best.
    return sorted(versions, key=cmp_to_key(compare_versions))

